array.string:
launchctl setenv XDG_CONFIG_HOME "$HOME/.config";
launchctl setenv XDG_DATA_HOME "$HOME/.local/share";
launchctl setenv XDG_STATE_HOME "$HOME/.local/state";
launchctl setenv XDG_CACHE_HOME "$HOME/.cache";
launchctl setenv NPM_CONFIG_INIT_MODULE "$HOME/.config/npm/config/npm-init.js";
launchctl setenv NPM_CONFIG_CACHE "$HOME/.cache/npm";
launchctl setenv NPM_CONFIG_USERCONFIG "$HOME/.config/npm/npmrc";
launchctl setenv CARGO_HOME "$HOME/.local/share/cargo";
launchctl setenv DOCKER_CONFIG "$HOME/.config/docker";
launchctl setenv GNUPGHOME "$HOME/.local/share/gnupg";
launchctl setenv GOPATH "$HOME/.local/share/go";
launchctl setenv VOLTA_HOME "$HOME/.local/share/volta";
launchctl setenv GRADLE_USER_HOME "$HOME/.local/share/gradle";
launchctl setenv ANDROID_HOME "$HOME/.local/share/android";
launchctl setenv LESSHISTFILE "$HOME/.cache/less/history";
